DROP TABLE IF EXISTS `sch__jurusan`;
CREATE TABLE `sch__jurusan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_unit` int NOT NULL,
  `nama_jurusan` varchar(100) NOT NULL,
  `kode_jurusan` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_unit` (`id_unit`),
  CONSTRAINT `sch__jurusan_ibfk_1` FOREIGN KEY (`id_unit`) REFERENCES `sch__unit` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

