DROP TABLE IF EXISTS `sch__kelas`;
CREATE TABLE `sch__kelas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_unit` int NOT NULL,
  `id_jurusan` int DEFAULT NULL,
  `tingkat` int NOT NULL,
  `kelas` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `id_walas` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_unit` (`id_unit`),
  KEY `id_walas` (`id_walas`),
  KEY `id_jurusan` (`id_jurusan`),
  CONSTRAINT `sch__kelas_ibfk_10` FOREIGN KEY (`id_walas`) REFERENCES `sch__guru` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `sch__kelas_ibfk_11` FOREIGN KEY (`id_jurusan`) REFERENCES `sch__jurusan` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `sch__kelas_ibfk_9` FOREIGN KEY (`id_unit`) REFERENCES `sch__unit` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

