DROP TABLE IF EXISTS `sch__nama_kolom`;
CREATE TABLE `sch__nama_kolom` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_group` int DEFAULT NULL,
  `id_kolom` int DEFAULT NULL,
  `order` int DEFAULT NULL,
  `nama_kolom` varchar(50) NOT NULL DEFAULT '',
  `is_fk` enum('0','1') NOT NULL DEFAULT '0',
  `nama_fk` varchar(50) DEFAULT NULL,
  `view_kolom` varchar(50) DEFAULT NULL,
  `tipe` enum('int','string','float','date','table') NOT NULL DEFAULT 'string',
  `hidden` enum('1','0') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
  `label` varchar(100) NOT NULL DEFAULT '',
  `input` varchar(50) NOT NULL DEFAULT 'input',
  `prepend` varchar(50) NOT NULL DEFAULT '',
  `append` varchar(50) NOT NULL DEFAULT '',
  `from_user` enum('0','1') NOT NULL DEFAULT '1',
  `input_only` enum('0','1') NOT NULL DEFAULT '0',
  `required` enum('0','1') NOT NULL DEFAULT '1',
  `rules` varchar(200) DEFAULT NULL,
  `default` varchar(50) NOT NULL DEFAULT '',
  `search` enum('0','1') NOT NULL DEFAULT '0',
  `function` varchar(50) NOT NULL DEFAULT '',
  `function_input` varchar(50) NOT NULL DEFAULT '',
  `function_submit` varchar(50) NOT NULL DEFAULT '',
  `placeholder` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `show` enum('1','0') NOT NULL DEFAULT '1',
  `width` varchar(10) NOT NULL DEFAULT '',
  `min_width` varchar(10) NOT NULL DEFAULT '',
  `width_input` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `align` varchar(10) NOT NULL DEFAULT '',
  `sortable` enum('0','1') NOT NULL DEFAULT '1',
  `allow_create` enum('0','1') NOT NULL DEFAULT '0',
  `allow_add` enum('0','1') NOT NULL DEFAULT '0',
  `add_href` varchar(100) NOT NULL DEFAULT '',
  `add_reset` varchar(100) NOT NULL DEFAULT '',
  `add_col` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `folder` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `created_at` datetime DEFAULT NULL,
  `pilihan` varchar(1000) NOT NULL DEFAULT '',
  `colspan` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '6',
  PRIMARY KEY (`id`),
  KEY `id_group` (`id_group`),
  KEY `id_kolom` (`id_kolom`),
  CONSTRAINT `sch__nama_kolom_ibfk_2` FOREIGN KEY (`id_group`) REFERENCES `sch__nama_tabel` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `sch__nama_kolom_ibfk_3` FOREIGN KEY (`id_kolom`) REFERENCES `sch__nama_kolom` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

