DROP TABLE IF EXISTS `sch_aka_nilai`;
CREATE TABLE `sch_aka_nilai` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_pembagian_mapel` int NOT NULL,
  `id_santri` int NOT NULL,
  `nilai_harian` float NOT NULL DEFAULT '0',
  `uts` float NOT NULL DEFAULT '0',
  `uas` float NOT NULL DEFAULT '0',
  `nilai_rapor` float NOT NULL DEFAULT '0',
  `katrol1` float NOT NULL DEFAULT '0',
  `katrol2` float NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_pembagian_mapel_id_santri` (`id_pembagian_mapel`,`id_santri`),
  KEY `id_santri` (`id_santri`),
  KEY `id_pembagian_mapel` (`id_pembagian_mapel`),
  CONSTRAINT `sch_aka_nilai_ibfk_2` FOREIGN KEY (`id_santri`) REFERENCES `sch__santri` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `sch_aka_nilai_ibfk_4` FOREIGN KEY (`id_pembagian_mapel`) REFERENCES `sch_aka_pembagian_mapel` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

