DROP TABLE IF EXISTS `sch_aka_pembagian_mapel`;
CREATE TABLE `sch_aka_pembagian_mapel` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_semester` int DEFAULT NULL,
  `id_guru` int NOT NULL,
  `id_kelas` int NOT NULL,
  `id_mapel` int NOT NULL,
  `kode_mapel` varchar(5) NOT NULL,
  `jam` int NOT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id_semester_id_kelas_id_mapel` (`id_semester`,`id_kelas`,`id_mapel`),
  KEY `id_guru` (`id_guru`),
  KEY `id_kelas` (`id_kelas`),
  KEY `id_mapel` (`id_mapel`),
  CONSTRAINT `sch_aka_pembagian_mapel_ibfk_11` FOREIGN KEY (`id_guru`) REFERENCES `sch__guru` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `sch_aka_pembagian_mapel_ibfk_12` FOREIGN KEY (`id_semester`) REFERENCES `sch__semester` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `sch_aka_pembagian_mapel_ibfk_13` FOREIGN KEY (`id_kelas`) REFERENCES `sch__kelas` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `sch_aka_pembagian_mapel_ibfk_14` FOREIGN KEY (`id_mapel`) REFERENCES `sch_aka_mapel` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

