DROP TABLE IF EXISTS `sch_pengguna`;
CREATE TABLE `sch_pengguna` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_guru` int DEFAULT NULL,
  `username` varchar(20) NOT NULL,
  `password` varchar(200) NOT NULL,
  `nama` varchar(50) NOT NULL,
  `id_unit` int NOT NULL,
  `vertical` enum('0','1') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '1',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id_guru` (`id_guru`),
  KEY `id_unit` (`id_unit`),
  CONSTRAINT `sch_pengguna_ibfk_2` FOREIGN KEY (`id_guru`) REFERENCES `sch__guru` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `sch_pengguna_ibfk_3` FOREIGN KEY (`id_unit`) REFERENCES `sch__unit` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

